dialogue.htmlContent:
		[##
			var loader = COLOUR_COVERING_RED.getClass().getClassLoader();
			var MainClass = loader.loadClass("com.lilithsthrone.main.Main");
			var mainController = MainClass.getDeclaredField("mainController").get(null);
			var engine = mainController.getWebEngine();
			var webView = mainController.getWebViewMain();
			
			function vibration(strength, duration, cycles, ogCycles) {
				var tt = loader.loadClass("javafx.animation.TranslateTransition").getConstructor().newInstance();
				tt.setNode(webView);
				
				var mult = (0.001 + 1.0 * cycles)/(0.001 + 1.0 * ogCycles);
				tt.setFromX(-15.0 + RND.nextInt(30));
				tt.setFromY(-15.0 + RND.nextInt(30));
				if (cycles == ogCycles) {
					tt.setFromX(0);
					tt.setFromY(0);
				}

				tt.setByX(-strength * mult + 2 * strength * mult * RND.nextDouble());
				tt.setByY(-strength * mult + 2 * strength * mult * RND.nextDouble());

				tt.setCycleCount(1);
				tt.setDuration(tt.getDuration().multiply(duration / (0.25 + 0.75 * mult)));
				tt.setAutoReverse(true);
				if(cycles > 1) {
					tt.setOnFinished(function (event) {
						vibration(strength, duration, cycles - 1, ogCycles);
					});
				} else {
					tt.setOnFinished(function(event) {
						var resetTT = loader.loadClass("javafx.animation.TranslateTransition").getConstructor().newInstance();
						resetTT.setNode(webView);
						resetTT.setFromX(webView.getTranslateX());
						resetTT.setFromY(webView.getTranslateY());
						resetTT.setToX(0);
						resetTT.setToY(0);
						resetTT.setDuration(tt.getDuration().multiply(0.25));
						resetTT.setCycleCount(1);
						resetTT.play();
					});
				}
				tt.play();
			};
		]
		#IF(flags.getSavedLong('idol_fury_count') == 0)
			<p>
				Having had enough of this joke of a friendship between you and [idol.name], you step forwards and sneer, [pc.speech(You know, I never really expected much of you, being the worthless trash that you are, yet somehow I'm still disappointed by how pathetic you are.)]
			</p>
			<p>
				#IF(pc.hasFetish(FETISH_SADIST))
					You see her relaxed expresion turns cold as you deliver the crushing insult, and, feeling particularly sadistic today, you continue, [pc.speech(Aww, what's the matter? Going to cry? You disgust me. To think that the citizens of Dominion put up with the likes of you skulking around in their city. All you're really good for is being a slave. At least then someone could make use of you as a cock-sleeve.)]
				#ELSE
					You see her relaxed expresion turns cold as you deliver the crushing insult, and you continue, [pc.speech(Knock it off. You don't get to play the victim here, having attacked and mugged countless innocent people!)]
				#ENDIF
			</p>
			<p>
				[idol.speech(...)] she is surprisingly calm from being betrayed by the only friend [idol.she] ever had. [idol.speech(...do you really mean what you said?)]
			</p>
			<p>
				[pc.speech(Of course I do!)] you say, grinning at [idol.name] as you prepare to attack her.
			</p>
			<p>
				[idol.speech(I see.)] 
			</p>
			<p>
				In an instant, you're engulfed in a fiery explosion! Yelping by the sudden flames, you roll around the floor, trying to snuff out the fires. But no matter what you do, it keeps clinging onto you stubbornly! Your powerful arcane aura is protecting you from most of the damage, so you don't get burned, but it still hurts pretty badly. 
			</p>
			<p>
				You see her walking towards you from the corners of your [pc.eyes], before standing above you, her feet in your view. Then you're suddenly sent flying into the air by her kick, spending a graceful few minutes in the air... before dropping back down harshly on the floor. 
			</p>
			<p>
				Letting out a grunt of pain, you try to stand back up, but [idol.name] sits in your lap, before she rears back for a punch. 
			</p>
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 1)
			<p>
				<i>Punch!</i> [idol.speech(YOU FUCKING PIECE OF SHIT!)] 
			</p>
			[##pc.incrementHealth(-pc.getHealth() / 4)]
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 2)
			<p>
				<i>Punch!</i> [idol.speech(I put my trust in you, and <i>this is what I get?!</i>)] <i>Punch!</i> [idol.speech(You <i>HEARTLESS JERK!</i>)]
			</p>
			[##pc.incrementHealth(-pc.getHealth() / 4)]
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 3)
			<p>
				<i>Punch!</i> [idol.speech(DON'T YOU KNOW?!)]
			</p>
			[##vibration(10, 0.1, 12, 12)]
			[##pc.incrementHealth(-pc.getHealth() / 4)]
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 4)
			<p style='text-align:center; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);'>
				<b>[pc.speech(That YOUR ACTIONS!)]</b>
			</p>
			[##vibration(20, 0.1, 12, 12)]
			[##pc.incrementHealth(-pc.getHealth() / 2)]
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 5)
			<p style='font-size: 50px; text-align:center; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);'>
				<b>[pc.speech(HAVE!)]</b>
			</p>
			[##vibration(20, 0.1, 12, 12)]
			[##pc.incrementHealth(-pc.getHealth() / 2)]
		#ELSEIF(flags.getSavedLong('idol_fury_count') == 6)
			<p style='font-size: 100px; text-align:center; position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%);'>
				<b>[pc.speech(CONSEQUENCES!?)]</b>
			</p>
			[##vibration(20, 0.1, 20, 20)]
			[##pc.incrementHealth(-pc.getHealth() / 2)]
		#ELSE
			<p>
				With a final punch in the face for good measure, she lets you drop on the ground like a sack of potatoes. She stands back up, looking at you with eyes filled with hatred and grief, before she turns around and leaves without a word. 
			</p>
			[##vibration(10, 0.1, 12, 12)]
			[##pc.setHealth(1)]
		#ENDIF
